CREATE TABLE IF NOT EXISTS products (id BIGSERIAL PRIMARY KEY,title TEXT NOT NULL,product_url TEXT NOT NULL,affiliate_url TEXT NOT NULL,price NUMERIC(12,2),currency CHAR(3) NOT NULL DEFAULT 'BRL',status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','inactive')),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS campaigns (id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,channel TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS campaign_products (campaign_id BIGINT NOT NULL REFERENCES campaigns(id) ON DELETE CASCADE,product_id BIGINT NOT NULL REFERENCES products(id) ON DELETE CASCADE,PRIMARY KEY(campaign_id,product_id));
